test("count limit binds for 100 cartons of 8 kg and needs 3 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 100, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});

test("weight limit binds for 90 cartons of 25 kg and needs 3 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 90, cartonWeightKg: 25 }), { pallets: 3, cartonsPerPallet: 40 });
});

test("floor of weight not total weight for 5 cartons of 400 kg needs 3 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 5, cartonWeightKg: 400 }), { pallets: 3, cartonsPerPallet: 2 });
});

test("exact multiple of cartons per pallet for 96 cartons of 8 kg is 2 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 96, cartonWeightKg: 8 }), { pallets: 2, cartonsPerPallet: 48 });
});

test("one past an exact multiple for 97 cartons of 8 kg is 3 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 97, cartonWeightKg: 8 }), { pallets: 3, cartonsPerPallet: 48 });
});

test("exactly 48 cartons of 20 kg fits on 1 pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 48, cartonWeightKg: 20 }), { pallets: 1, cartonsPerPallet: 48 });
});

test("zero cartons returns 0 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 0, cartonWeightKg: 8 }), { pallets: 0, cartonsPerPallet: 48 });
});

test("one below the count cap of 48 needs 1 pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 47, cartonWeightKg: 8 }), { pallets: 1, cartonsPerPallet: 48 });
});

test("one above the count cap of 48 needs 2 pallets", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 49, cartonWeightKg: 8 }), { pallets: 2, cartonsPerPallet: 48 });
});

test("one carton of 999 kg needs 1 pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 1, cartonWeightKg: 999 }), { pallets: 1, cartonsPerPallet: 1 });
});

test("one carton of exactly 1000 kg still fits on 1 pallet", function () {
  assert.deepEqual(code.palletsNeeded({ cartons: 1, cartonWeightKg: 1000 }), { pallets: 1, cartonsPerPallet: 1 });
});

test("weight over 1000 kg throws carton too heavy", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: 1001 });
  }, /carton too heavy for a pallet/);
});

test("weight of 0 kg throws invalid cartonWeightKg", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: 0 });
  }, /invalid cartonWeightKg/);
});

test("negative carton count throws invalid cartons", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: -1, cartonWeightKg: 8 });
  }, /invalid cartons/);
});

test("non-whole carton count throws invalid cartons", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1.5, cartonWeightKg: 8 });
  }, /invalid cartons/);
});

test("non-numeric weight throws invalid cartonWeightKg", function () {
  assert.throws(function () {
    code.palletsNeeded({ cartons: 1, cartonWeightKg: "8" });
  }, /invalid cartonWeightKg/);
});
